using FluentValidation; using SmartWaste.Application.Collection.DTOs.Requests;
namespace SmartWaste.Application.Collection.Validation;
public sealed class CreateCollectionAssignmentRequestValidator:AbstractValidator<CreateCollectionAssignmentRequest>{public CreateCollectionAssignmentRequestValidator(){RuleFor(x=>x.DriverId).NotEmpty();RuleFor(x=>x.VehicleId).NotEmpty();RuleFor(x=>x.CollectionTaskIds).NotEmpty().Must(x=>x.Distinct().Count()==x.Count).WithMessage("Task IDs must be unique.");RuleFor(x=>x.Stops).NotEmpty();RuleForEach(x=>x.Stops).ChildRules(s=>{s.RuleFor(x=>x.CollectionTaskId).NotEmpty();s.RuleFor(x=>x.Sequence).GreaterThan(0);});RuleFor(x=>x.Stops).Must(x=>x.Select(s=>s.CollectionTaskId).Distinct().Count()==x.Count).WithMessage("Stops must not duplicate tasks.").Must(x=>x.Select(s=>s.Sequence).OrderBy(s=>s).SequenceEqual(Enumerable.Range(1,x.Count))).WithMessage("Stop sequences must be contiguous from 1.");RuleFor(x=>x.CompatibilityAcknowledgement).MaximumLength(500).When(x=>x.CompatibilityAcknowledgement is not null);}}
